-- PostgreSQL schema + seed for the dialect-compat tests. Single file so it
-- can be passed to PostgreSQLContainer.withInitScript(...) which only takes
-- one resource. Uses PostgreSQL's GENERATED BY DEFAULT AS IDENTITY (Postgres
-- 10+) — that matches the H2 schema syntax, but the underlying behaviour is
-- the real PostgreSQL sequence implementation.
CREATE TABLE IF NOT EXISTS test_users (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);

